import zipfile
import json
import csv
from lxml import etree


def load_updates(path: str) -> dict:
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def load_followups(path: str):
    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)
    return sorted(rows, key=lambda r: int(r['sequence']))


def get_nsmap(root):
    # lxml uses None for default namespaces; section files use hp prefix in this task.
    ns = {}
    for k, v in (root.nsmap or {}).items():
        if k is None:
            continue
        ns[k] = v
    if 'hp' not in ns:
        # Fallback for safety
        ns['hp'] = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
    return ns


def paragraph_text(p, ns):
    # Concatenate all hp:t descendants
    parts = []
    for t in p.xpath('.//hp:t', namespaces=ns):
        parts.append(t.text or '')
    return ''.join(parts)


def set_paragraph_text_single_run(p, ns, new_text: str):
    """
    Replace paragraph text by setting first hp:t to new_text and clearing the rest.
    Keeps structure largely intact but ensures no duplicate remnants remain.
    """
    t_nodes = p.xpath('.//hp:t', namespaces=ns)
    if not t_nodes:
        # If no text nodes exist, create a minimal run/t node.
        run = etree.SubElement(p, f"{{{ns['hp']}}}run")
        run.set('charPrIDRef', '0')
        t = etree.SubElement(run, f"{{{ns['hp']}}}t")
        t.text = new_text
        return

    t_nodes[0].text = new_text
    for t in t_nodes[1:]:
        t.text = ''


def replace_text_across_runs(p, ns, old: str, new: str):
    """Replace substring in each hp:t node independently."""
    changed = False
    for t in p.xpath('.//hp:t', namespaces=ns):
        if t.text and old in t.text:
            t.text = t.text.replace(old, new)
            changed = True
    return changed


def remove_layout_cache(p, ns):
    # Task mentions <hp:lineSegArray> but observed XML uses <hp:linesegarray>
    # Remove either capitalization and nested lineseg elements.
    removed = False
    for tag in ['linesegarray', 'lineSegArray', 'lineseg', 'lineSeg']:
        nodes = p.xpath(f'./hp:{tag}', namespaces=ns)
        for n in nodes:
            p.remove(n)
            removed = True
    # Also remove any descendant cache elements just in case
    for tag in ['linesegarray', 'lineSegArray', 'lineseg', 'lineSeg']:
        nodes = p.xpath(f'.//hp:{tag}', namespaces=ns)
        for n in nodes:
            parent = n.getparent()
            if parent is not None:
                parent.remove(n)
                removed = True
    return removed


def is_appendix_paragraph(p, ns):
    return '이 부록 문단은 그대로 유지해야 합니다.' in paragraph_text(p, ns)


def update_section0(tree, updates):
    ns = get_nsmap(tree)

    # Build exact old->new mapping based on observed current document text.
    # Customer is split across runs: "Northwind " + "Retail".
    mappings = {
        'Northwind Retail': updates['customer'],
        '이전담당자': updates['owner_name'],
        '2025-04-01 ~ 2025-04-15': f"{updates['window_start']} ~ {updates['window_end']}",
        'Standard-18M': updates['band'],
        'ops-old@northwind.example': updates['escalation_email'],
        '기존 메모를 새 메모로 바꾸세요.': updates['note'],
    }

    modified_paragraphs = set()

    # Update paragraphs
    for p in tree.xpath('.//hp:p', namespaces=ns):
        if is_appendix_paragraph(p, ns):
            continue

        full = paragraph_text(p, ns)

        # Special handling: customer line is split into two runs.
        if '고객사:' in full and 'Northwind' in full and 'Retail' in full:
            # Replace from "고객사:" onward to keep prefix exactly.
            # Expected current: "고객사: Northwind Retail"
            prefix = '고객사: '
            if prefix in full:
                new_full = prefix + updates['customer']
                set_paragraph_text_single_run(p, ns, new_full)
                modified_paragraphs.add(p)
                continue

        # Renewal window paragraph
        if '갱신 윈도우:' in full and '2025-04-01' in full:
            old_window = '2025-04-01 ~ 2025-04-15'
            new_window = f"{updates['window_start']} ~ {updates['window_end']}"
            if replace_text_across_runs(p, ns, old_window, new_window):
                modified_paragraphs.add(p)
            continue

        # For other fields, do substring replacement within runs.
        changed_here = False
        for old, new in mappings.items():
            if old in full:
                # When the old value spans runs, fall back to full reset.
                if old == 'Northwind Retail':
                    continue
                if replace_text_across_runs(p, ns, old, new):
                    changed_here = True
        if changed_here:
            modified_paragraphs.add(p)

    # Remove layout cache for modified paragraphs
    for p in modified_paragraphs:
        remove_layout_cache(p, ns)

    return len(modified_paragraphs)


def update_section1(tree, updates, followups):
    ns = get_nsmap(tree)
    modified_paragraphs = set()

    # Replace the 3 existing follow-up lines (ids 41-43 in observed document)
    # We will find paragraphs whose text starts with "1. old follow-up" etc.
    items = [r['item'] for r in followups]
    if len(items) < 3:
        raise ValueError(f"followups.csv has {len(items)} items; expected at least 3")

    followup_targets = []
    for p in tree.xpath('.//hp:p', namespaces=ns):
        if is_appendix_paragraph(p, ns):
            continue
        t = paragraph_text(p, ns)
        if t.strip().startswith('1. old follow-up'):
            followup_targets.append((1, p))
        elif t.strip().startswith('2. old follow-up'):
            followup_targets.append((2, p))
        elif t.strip().startswith('3. old follow-up'):
            followup_targets.append((3, p))

    # Ensure deterministic ordering by number
    followup_targets.sort(key=lambda x: x[0])
    if len(followup_targets) != 3:
        raise ValueError(f"Could not find 3 follow-up paragraphs to replace; found {len(followup_targets)}")

    for idx, p in followup_targets:
        new_text = f"{idx}. {items[idx-1]}"
        set_paragraph_text_single_run(p, ns, new_text)
        modified_paragraphs.add(p)

    # Update renewal window confirmation line
    for p in tree.xpath('.//hp:p', namespaces=ns):
        if is_appendix_paragraph(p, ns):
            continue
        full = paragraph_text(p, ns)
        if full.startswith('갱신 윈도우 확인:') and '2025-04-01' in full:
            old_window = '2025-04-01 ~ 2025-04-15'
            new_window = f"{updates['window_start']} ~ {updates['window_end']}"
            if replace_text_across_runs(p, ns, old_window, new_window):
                modified_paragraphs.add(p)

    for p in modified_paragraphs:
        remove_layout_cache(p, ns)

    return len(modified_paragraphs)


def main():
    updates = load_updates('renewal_update.json')
    followups = load_followups('followups.csv')

    original_zip = 'renewal_playbook.hwpx'
    entries = {}
    order = []
    with zipfile.ZipFile(original_zip, 'r') as zf:
        for info in zf.infolist():
            order.append(info.filename)
            entries[info.filename] = zf.read(info.filename)

    # Update section0.xml
    sec0_bytes = entries['Contents/section0.xml']
    sec0_root = etree.fromstring(sec0_bytes)
    mod0 = update_section0(sec0_root, updates)
    entries['Contents/section0.xml'] = etree.tostring(sec0_root, xml_declaration=True, encoding='UTF-8')

    # Update section1.xml (followups live here in this document)
    sec1_bytes = entries['Contents/section1.xml']
    sec1_root = etree.fromstring(sec1_bytes)
    mod1 = update_section1(sec1_root, updates, followups)
    entries['Contents/section1.xml'] = etree.tostring(sec1_root, xml_declaration=True, encoding='UTF-8')

    # Write output zip; ensure mimetype rule if present
    output_path = '/root/renewal_playbook_updated.hwpx'
    with zipfile.ZipFile(output_path, 'w') as zout:
        if 'mimetype' in entries:
            zout.writestr('mimetype', entries['mimetype'], compress_type=zipfile.ZIP_STORED)
        for name in order:
            if name == 'mimetype':
                continue
            data = entries[name]
            # Keep original compression type? Use deflated for non-mimetype.
            zout.writestr(name, data, compress_type=zipfile.ZIP_DEFLATED)

    print(f"Updated sections: section0 modified paragraphs={mod0}, section1 modified paragraphs={mod1}")
    print(f"Wrote {output_path}")


if __name__ == '__main__':
    main()

